package datatable

// ColumnShape is what a cross-view guard reads of a column without knowing the
// row type T: the declared nature of the column, not its cells.
type ColumnShape struct {
	Title    string
	Sizing   Sizing
	MinWidth int
	// Indicator, Less and Search report whether the column declares an activity
	// indicator, a comparator and a search text.
	Indicator, Less, Search bool
}

// Shapes returns the non-generic shape of every declared column, in order. A
// fresh slice is built on each call, so the caller cannot alter the table.
func (m *Model[T]) Shapes() []ColumnShape {
	shapes := make([]ColumnShape, len(m.cfg.Columns))
	for i, c := range m.cfg.Columns {
		shapes[i] = ColumnShape{
			Title:     c.Title,
			Sizing:    c.Sizing,
			MinWidth:  c.MinWidth,
			Indicator: c.Indicator != nil,
			Less:      c.Less != nil,
			Search:    c.Search != nil,
		}
	}
	return shapes
}

// ActivityTable is the face of a table a cross-view guard inspects. It is
// read-only: *Model[T] satisfies it for any T.
type ActivityTable interface {
	Shapes() []ColumnShape
	RenderedWidth() int
}
		return less(items[i], items[j])
	})
	return items
}

// Span is one coloured run of a multi-run cell (Column.Spans): Width cells of
// the cell's already-fitted text, painted with Style. Style must not carry
// Width, Padding or Margin: they would change the cell's width (as for Cut).
type Span struct {
	Width int
	Style lipgloss.Style
}

// IndicatorColumn builds the activity column (Rule 125 shape: untitled, fixed,
// IconColumnWidth). It is the only way a view builds one. Only the first column
// carrying an Indicator is honoured (Model.indicatorAt); later ones are ignored.
func IndicatorColumn[T any](state func(T) indicator.State,
	rest func(T) string, restStyle func(T) lipgloss.Style) Column[T] {
	c := Column[T]{
		Sizing: SizingFixed, MinWidth: IconColumnWidth,
		Indicator: state,
		Cell: func(item T) string {
			if rest == nil {
				return ""
			}
			return rest(item)
		},
	}
	if restStyle != nil {
		c.Style = restStyle
	}
	return c
}

// SetBlinkPhase sets the phase read at render. Read at render; nothing is rebuilt.
func (m *Model[T]) SetBlinkPhase(on bool) { m.blinkOn = on }

// BlinkPhase reports the current blink phase.
func (m *Model[T]) BlinkPhase() bool { return m.blinkOn }
